using FluentAssertions; using FluentValidation; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Diagnostics; using Moq; using SmartWaste.Application.Collection.DTOs.Requests; using SmartWaste.Application.Common.Exceptions; using SmartWaste.Domain.Collection.Entities; using SmartWaste.Domain.Collection.Enums; using SmartWaste.Domain.Common; using SmartWaste.Domain.Entities; using SmartWaste.Domain.Reporting.Entities; using SmartWaste.Domain.Reporting.Enums; using SmartWaste.Infrastructure.Collection.Services; using SmartWaste.Infrastructure.Persistence;
namespace SmartWaste.Tests.Collection.Services;
public class CollectionAssignmentServiceTests
{
 private static AppDbContext Db()=>new(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).ConfigureWarnings(x=>x.Ignore(InMemoryEventId.TransactionIgnoredWarning)).Options);
 private static UserManager<AppUser> Users(bool driver=true){var store=new Mock<IUserStore<AppUser>>();var manager=new Mock<UserManager<AppUser>>(store.Object,null!,null!,null!,null!,null!,null!,null!,null!);manager.Setup(x=>x.IsInRoleAsync(It.IsAny<AppUser>(),AppRoles.Driver)).ReturnsAsync(driver);return manager.Object;}
 [Fact] public async Task Create_RejectsNonOfficer(){await using var db=Db();var service=new CollectionAssignmentService(db,Users());Func<Task> action=()=>service.CreateAsync(new CreateCollectionAssignmentRequest(),Guid.NewGuid(),AppRoles.MunicipalManager);await action.Should().ThrowAsync<ForbiddenException>();}
 [Theory] [InlineData(AppRoles.MunicipalManager)] [InlineData(AppRoles.Driver)] [InlineData(AppRoles.Citizen)] public async Task Reorder_RejectsNonWasteOfficer(string role){await using var db=Db();var service=new CollectionAssignmentService(db,Users());Func<Task> action=()=>service.ReorderStopsAsync(Guid.NewGuid(),new ReorderRouteStopsRequest(),Guid.NewGuid(),role);await action.Should().ThrowAsync<ForbiddenException>();}
 [Fact] public async Task Create_AssignsScheduledTaskWithClaimRouteAndHistory(){await using var db=Db();var driverUser=new AppUser{Id=Guid.NewGuid(),FullName="Driver",UserName="driver",IsActive=true};var officer=new AppUser{Id=Guid.NewGuid(),FullName="Officer",UserName="officer"};var driver=new DriverProfile{UserId=driverUser.Id,User=driverUser,LicenseNumber="LIC",AvailabilityStatus=DriverAvailabilityStatus.Available,IsEligible=true};var vehicle=new Vehicle{Id=Guid.NewGuid(),RegistrationNumber="C3-SVC",CapacityLiters=100,OperationalStatus=VehicleOperationalStatus.Available};var task=new CollectionTask{Id=Guid.NewGuid(),TaskCode="TASK",Status=CollectionTaskStatus.Scheduled,ScheduledAt=DateTime.UtcNow,WasteReportId=Guid.NewGuid()};db.AddRange(driverUser,officer,driver,vehicle,task);await db.SaveChangesAsync();var request=new CreateCollectionAssignmentRequest{DriverId=driver.UserId,VehicleId=vehicle.Id,CollectionTaskIds=new[]{task.Id},Stops=new[]{new CreateRouteStopRequest{CollectionTaskId=task.Id,Sequence=1}}};var result=await new CollectionAssignmentService(db,Users()).CreateAsync(request,officer.Id,AppRoles.WasteOfficer);result.Status.Should().Be(CollectionAssignmentStatus.Assigned);(await db.CollectionAssignmentTaskClaims.SingleAsync()).IsActive.Should().BeTrue();(await db.CollectionTasks.SingleAsync()).Status.Should().Be(CollectionTaskStatus.Assigned);(await db.CollectionTaskStatusHistories.SingleAsync()).FromStatus.Should().Be(CollectionTaskStatus.Scheduled);(await db.Routes.SingleAsync()).RoutingMethod.Should().Be(RoutingMethod.ManualOrder);}
 [Fact] public async Task Reorder_UsesValidAssignmentGraphAndPreservesC2SourceState(){await using var db=Db();var driverUser=new AppUser{Id=Guid.NewGuid(),FullName="Driver",UserName="driver",IsActive=true};var officer=new AppUser{Id=Guid.NewGuid(),FullName="Officer",UserName="officer"};var citizen=new AppUser{Id=Guid.NewGuid(),FullName="Citizen",UserName="citizen",IsActive=true};var driver=new DriverProfile{UserId=driverUser.Id,User=driverUser,LicenseNumber="LIC-REORDER",AvailabilityStatus=DriverAvailabilityStatus.Available,IsEligible=true};var vehicle=new Vehicle{Id=Guid.NewGuid(),RegistrationNumber="C3-REORDER",CapacityLiters=100,OperationalStatus=VehicleOperationalStatus.Available};vehicle.SupportedWasteTypes.Add(new VehicleSupportedWasteType{WasteType=WasteType.General});var report=new WasteReport{CitizenId=citizen.Id,Description="Report target",WasteType=WasteType.General,Latitude=6.9,Longitude=79.9,Status=WasteReportStatus.Scheduled};var bin=new WasteBin{BinCode="C3-REORDER-BIN",CapacityLiters=100,Latitude=6.91,Longitude=79.91,AdministrativeStatus=BinAdministrativeStatus.Active};bin.AcceptedWasteTypes.Add(new WasteBinAcceptedWasteType{WasteType=WasteType.General});var reportTask=new CollectionTask{Id=Guid.NewGuid(),TaskCode="REPORT-TASK",Status=CollectionTaskStatus.Scheduled,ScheduledAt=DateTime.UtcNow,WasteReportId=report.Id,CollectionReason=CollectionReason.VerifiedReport,CreatedByUserId=officer.Id};var binTask=new CollectionTask{Id=Guid.NewGuid(),TaskCode="BIN-TASK",Status=CollectionTaskStatus.Scheduled,ScheduledAt=DateTime.UtcNow,WasteBinId=bin.Id,CollectionReason=CollectionReason.OfficerDiscretion,SchedulingReason="Manual test",CreatedByUserId=officer.Id};db.AddRange(driverUser,officer,citizen,driver,vehicle,report,bin,reportTask,binTask);await db.SaveChangesAsync();var service=new CollectionAssignmentService(db,Users());var assignment=await service.CreateAsync(new CreateCollectionAssignmentRequest{DriverId=driver.UserId,VehicleId=vehicle.Id,CollectionTaskIds=new[]{reportTask.Id,binTask.Id},Stops=new[]{new CreateRouteStopRequest{CollectionTaskId=reportTask.Id,Sequence=1},new CreateRouteStopRequest{CollectionTaskId=binTask.Id,Sequence=2}}},officer.Id,AppRoles.WasteOfficer);var original=assignment.Route!.Stops.ToDictionary(x=>x.Task.Id,x=>x);var reordered=await service.ReorderStopsAsync(assignment.Id,new ReorderRouteStopsRequest{Stops=new[]{new RouteStopSequenceRequest{RouteStopId=original[binTask.Id].Id,Sequence=1},new RouteStopSequenceRequest{RouteStopId=original[reportTask.Id].Id,Sequence=2}}},officer.Id,AppRoles.WasteOfficer);reordered.Stops.Select(x=>x.Task.Id).Should().Equal(binTask.Id,reportTask.Id);var stored=await db.Routes.Include(x=>x.Stops).SingleAsync(x=>x.CollectionAssignmentId==assignment.Id);stored.Stops.OrderBy(x=>x.Sequence).Select(x=>x.Id).Should().Equal(original[binTask.Id].Id,original[reportTask.Id].Id);stored.Stops.Select(x=>x.CollectionTaskId).Should().BeEquivalentTo(new[]{reportTask.Id,binTask.Id});stored.Stops.Select(x=>x.CollectionAssignmentTaskClaimId).Should().OnlyHaveUniqueItems();(await db.CollectionAssignments.SingleAsync(x=>x.Id==assignment.Id)).Status.Should().Be(CollectionAssignmentStatus.Assigned);(await db.CollectionTasks.Where(x=>x.Id==reportTask.Id||x.Id==binTask.Id).Select(x=>x.Status).ToListAsync()).Should().AllBeEquivalentTo(CollectionTaskStatus.Assigned);(await db.WasteReports.SingleAsync(x=>x.Id==report.Id)).Status.Should().Be(WasteReportStatus.Scheduled);(await db.WasteBins.SingleAsync(x=>x.Id==bin.Id)).LastCollectedAt.Should().BeNull();(await db.BinObservations.CountAsync(x=>x.WasteBinId==bin.Id)).Should().Be(0);}
 [Fact] public async Task Create_AllowsAvailableDriverWithLegacyIneligibleProfileAndNoLicence(){await using var db=Db();var driverUser=new AppUser{Id=Guid.NewGuid(),FullName="Driver",UserName="driver",IsActive=true};var officer=new AppUser{Id=Guid.NewGuid(),FullName="Officer",UserName="officer"};var driver=new DriverProfile{UserId=driverUser.Id,User=driverUser,AvailabilityStatus=DriverAvailabilityStatus.Available,IsEligible=false};var vehicle=new Vehicle{Id=Guid.NewGuid(),RegistrationNumber="C3-NO-LICENCE",CapacityLiters=100,OperationalStatus=VehicleOperationalStatus.Available};var task=new CollectionTask{Id=Guid.NewGuid(),TaskCode="NO-LICENCE-TASK",Status=CollectionTaskStatus.Scheduled,ScheduledAt=DateTime.UtcNow,WasteReportId=Guid.NewGuid()};db.AddRange(driverUser,officer,driver,vehicle,task);await db.SaveChangesAsync();var result=await new CollectionAssignmentService(db,Users()).CreateAsync(new CreateCollectionAssignmentRequest{DriverId=driver.UserId,VehicleId=vehicle.Id,CollectionTaskIds=new[]{task.Id},Stops=new[]{new CreateRouteStopRequest{CollectionTaskId=task.Id,Sequence=1}}},officer.Id,AppRoles.WasteOfficer);result.Status.Should().Be(CollectionAssignmentStatus.Assigned);}
}
